+  if (url.pathname === "/items") {
+    const limits = url.searchParams.getAll("limit");
+    const offsets = url.searchParams.getAll("offset");
+    if (
+      limits.length > 1 || offsets.length > 1 ||
+      (limits.length && (!/^\d+$/.test(limits[0]) || Number(limits[0]) < 1 || Number(limits[0]) > 50)) ||
+      (offsets.length && !/^\d+$/.test(offsets[0]))
+    ) {
+      return httpError(400, "invalid_pagination", "limit must be a whole number from 1 to 50 and offset a whole number from 0.");
+    }
+    const offset = offsets.length ? Number(offsets[0]) : 0;
+    const end = limits.length ? offset + Number(limits[0]) : undefined;
+    return { status: 200, body: items.slice(offset, end) };
+  }
+  if (url.pathname === "/expiring")
     return {
       status: 200,
       body: items.filter((i) => !isExpired(i, now) && daysLeft(i, now) <= 7),
